/**
 * Sign-off fingerprints and seals.
 * v1 (imported): SHA-256 / HMAC-SHA256 over Python `json.dumps(sort_keys=True, separators=(",", ":"))`
 *   (ensure_ascii, Python float repr): byte-exact port of v1 services/signoffs.py, proven by
 *   __fixtures__/seals-v1.json (generated by the stdlib script next to it).
 * v2: same period data over RFC 8785 canonical JSON. Key: sha256("resorixtrack-signoff:" + SIGNOFF_KEY).
 * Seals chain per person: each seal covers the previous seal of that person, whatever its version.
 */
import { createHash, createHmac, timingSafeEqual } from "node:crypto"
import { and, asc, desc, eq, gt, gte, isNull, lt, lte, or } from "drizzle-orm"
import { isRecord } from "@/lib/guards"
import { db } from "../db"
import { toInstant } from "../db/columns"
import { absences, balanceAdjustments, type MonthSignoff, monthSignoffs, timeEntries, workLogs } from "../db/schema"
import { env } from "../env"

export type SealCheck = "ok" | "seal_mismatch" | "digest_mismatch" | "chain_broken"
export type SealVersion = 1 | 2

/** A Python `float` (serialised with Python's repr in v1, e.g. `30.0`, `1e-05`). */
export class PyFloat {
  constructor(readonly value: number) {}
}
/** A number literal kept exactly as written (v1 snapshots parsed from their stored JSON text). */
export class RawNumber {
  constructor(readonly literal: string) {}
}

export type Canon = null | boolean | number | string | PyFloat | RawNumber | Canon[] | { [k: string]: Canon }

// ------------------------------------------------------------------ Python json.dumps port

/** Python `repr(float)`: shortest round-trip digits, exponent form below 1e-4 and from 1e16. */
export function pyFloatRepr(x: number): string {
  if (Number.isNaN(x)) return "NaN"
  if (!Number.isFinite(x)) return x > 0 ? "Infinity" : "-Infinity"
  const sign = x < 0 || Object.is(x, -0) ? "-" : ""
  const [mant, expStr] = Math.abs(x).toExponential().split("e")
  const digits = mant.replace(".", "")
  const exp = Number(expStr)
  const decpt = exp + 1
  if (decpt <= -4 || decpt > 16) {
    const m = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits
    return `${sign}${m}e${exp < 0 ? "-" : "+"}${Math.abs(exp).toString().padStart(2, "0")}`
  }
  if (decpt <= 0) return `${sign}0.${"0".repeat(-decpt)}${digits}`
  if (decpt >= digits.length) return `${sign}${digits}${"0".repeat(decpt - digits.length)}.0`
  return `${sign}${digits.slice(0, decpt)}.${digits.slice(decpt)}`
}

const SHORT_ESCAPES: Record<string, string> = {
  '"': '\\"',
  "\\": "\\\\",
  "\n": "\\n",
  "\r": "\\r",
  "\t": "\\t",
  "\b": "\\b",
  "\f": "\\f",
}

/** Python `json.dumps` string with `ensure_ascii=True` (per UTF-16 code unit, lowercase hex). */
export function pyString(s: string): string {
  let out = '"'
  for (let i = 0; i < s.length; i++) {
    const ch = s[i]
    const c = s.charCodeAt(i)
    if (SHORT_ESCAPES[ch]) out += SHORT_ESCAPES[ch]
    else if (c < 0x20 || c > 0x7e) out += `\\u${c.toString(16).padStart(4, "0")}`
    else out += ch
  }
  return `${out}"`
}

/** Python sorts str keys by code point (JS `<` compares UTF-16 code units). */
function byCodePoint(a: string, b: string): number {
  const x = Array.from(a, (c) => c.codePointAt(0) ?? 0)
  const y = Array.from(b, (c) => c.codePointAt(0) ?? 0)
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

/** `json.dumps(value, sort_keys=True, separators=(",", ":"))`. Plain integral JS numbers are Python ints. */
export function pyDumps(v: Canon): string {
  if (v === null) return "null"
  if (typeof v === "boolean") return v ? "true" : "false"
  if (typeof v === "string") return pyString(v)
  if (typeof v === "number") return Number.isInteger(v) ? String(v) : pyFloatRepr(v)
  if (v instanceof PyFloat) return pyFloatRepr(v.value)
  if (v instanceof RawNumber) return v.literal
  if (Array.isArray(v)) return `[${v.map(pyDumps).join(",")}]`
  return `{${Object.keys(v)
    .sort(byCodePoint)
    .map((k) => `${pyString(k)}:${pyDumps(v[k])}`)
    .join(",")}}`
}

function toCanon(v: unknown): Canon {
  if (v === null || typeof v === "boolean" || typeof v === "number" || typeof v === "string") return v
  if (v instanceof RawNumber || v instanceof PyFloat) return v
  if (Array.isArray(v)) return v.map(toCanon)
  if (isRecord(v)) return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, toCanon(x)]))
  throw new Error("Not a JSON value")
}

/** Parse JSON text keeping every number literal as written (so Python floats like `1.0` survive). */
export function parseKeepingNumbers(text: string): Canon {
  return toCanon(
    JSON.parse(text, (_k, value: unknown, ctx?: { source?: string }) =>
      typeof value === "number" && ctx?.source != null ? new RawNumber(ctx.source) : value,
    ),
  )
}

// ------------------------------------------------------------------ RFC 8785 (JCS)

export function jcs(v: Canon): string {
  if (v === null || typeof v === "boolean" || typeof v === "string") return JSON.stringify(v)
  if (typeof v === "number" || v instanceof PyFloat || v instanceof RawNumber) {
    const n = typeof v === "number" ? v : v instanceof PyFloat ? v.value : Number(v.literal)
    if (!Number.isFinite(n)) throw new Error("JCS cannot represent NaN or Infinity")
    return JSON.stringify(n)
  }
  if (Array.isArray(v)) return `[${v.map(jcs).join(",")}]`
  return `{${Object.keys(v)
    .sort()
    .map((k) => `${JSON.stringify(k)}:${jcs(v[k])}`)
    .join(",")}}`
}

export function canonical(version: SealVersion, v: Canon): string {
  return version === 1 ? pyDumps(v) : jcs(v)
}

// ------------------------------------------------------------------ period data, digest, seal

/** v1 `_ts`: `%Y-%m-%dT%H:%M:%S.%f` in UTC without zone suffix. */
function ts(at: string | null): string | null {
  return at ? toInstant(at).slice(0, -1) : null
}

export type PeriodData = {
  work_logs: Canon[][]
  entries: Canon[][]
  absences: Canon[][]
  adjustments: Canon[][]
}

/** All rows that make up the period (including soft-deleted ones), in v1's structure. */
export function periodData(
  userId: number,
  startDate: string,
  endDate: string,
  startUtc: string,
  endUtc: string,
): PeriodData {
  const s = toInstant(startUtc)
  const e = toInstant(endUtc)
  const entries = db
    .select()
    .from(timeEntries)
    .where(
      and(
        eq(timeEntries.userId, userId),
        lt(timeEntries.startAt, e),
        or(isNull(timeEntries.endAt), gt(timeEntries.endAt, s)),
      ),
    )
    .orderBy(asc(timeEntries.id))
    .all()
  const abs = db
    .select()
    .from(absences)
    .where(and(eq(absences.userId, userId), lte(absences.startDate, endDate), gte(absences.endDate, startDate)))
    .orderBy(asc(absences.id))
    .all()
  const adjustments = db
    .select()
    .from(balanceAdjustments)
    .where(
      and(
        eq(balanceAdjustments.userId, userId),
        gte(balanceAdjustments.effectiveDate, startDate),
        lte(balanceAdjustments.effectiveDate, endDate),
      ),
    )
    .orderBy(asc(balanceAdjustments.id))
    .all()
  const logs = db
    .select()
    .from(workLogs)
    .where(and(eq(workLogs.userId, userId), gte(workLogs.date, startDate), lte(workLogs.date, endDate)))
    .orderBy(asc(workLogs.id))
    .all()
  return {
    work_logs: logs.map((w) => [
      w.id,
      w.date,
      w.projectId,
      w.customerRef,
      Math.trunc(w.minutes),
      w.note,
      w.isDeleted,
      w.startTime,
      w.endTime,
    ]),
    entries: entries.map((x) => [x.id, x.kind, ts(x.startAt), ts(x.endAt), x.isDeleted, x.note]),
    absences: abs.map((a) => [a.id, a.typeId, a.startDate, a.endDate, a.startHalf, a.endHalf, a.status]),
    adjustments: adjustments.map((a) => [a.id, a.account, new PyFloat(a.amount), a.effectiveDate, a.isDeleted]),
  }
}

export function periodDataOf(
  row: Pick<MonthSignoff, "userId" | "periodStartDate" | "periodEndDate" | "periodStartUtc" | "periodEndUtc">,
): PeriodData {
  return periodData(row.userId, row.periodStartDate, row.periodEndDate, row.periodStartUtc, row.periodEndUtc)
}

const sha256hex = (s: string) => createHash("sha256").update(s, "utf8").digest("hex")

/** Fingerprint of the period's time data (same canonical form as the seal's version). */
export function computeDigest(version: SealVersion, data: Canon): string {
  return sha256hex(canonical(version, data))
}

export function sealKey(secret: string = env.signoffKey): Buffer {
  return createHash("sha256").update(`resorixtrack-signoff:${secret}`, "utf8").digest()
}

export type SealRow = Pick<
  MonthSignoff,
  | "userId"
  | "month"
  | "periodStartDate"
  | "periodEndDate"
  | "periodStartUtc"
  | "periodEndUtc"
  | "signedById"
  | "signedAt"
  | "snapshot"
  | "digest"
  | "prevSeal"
  | "sealVersion"
>

/** The exact bytes the HMAC covers. v2 adds `"v":2` so a seal can never be read as another version. */
export function sealMessage(row: SealRow): string {
  const v1 = row.sealVersion === 1
  const at = (x: string) => (v1 ? ts(x) : toInstant(x))
  const payload: Record<string, Canon> = {
    user_id: row.userId,
    month: row.month,
    start: row.periodStartDate,
    end: row.periodEndDate,
    start_utc: at(row.periodStartUtc),
    end_utc: at(row.periodEndUtc),
    signed_by: row.signedById,
    signed_at: at(row.signedAt),
    snapshot: v1 ? parseKeepingNumbers(row.snapshot) : toCanon(JSON.parse(row.snapshot)),
    digest: row.digest,
    prev: row.prevSeal,
  }
  if (!v1) payload.v = 2
  return canonical(v1 ? 1 : 2, payload)
}

export function computeSeal(row: SealRow, key: Buffer = sealKey()): string {
  return createHmac("sha256", key).update(sealMessage(row), "utf8").digest("hex")
}

function sameText(a: string, b: string): boolean {
  const x = Buffer.from(a, "utf8")
  const y = Buffer.from(b, "utf8")
  return x.length === y.length && timingSafeEqual(x, y)
}

/** Check one person's chain: the first problem per sign-off id (`ok` when intact). */
export function checkUserChain(userId: number, key: Buffer = sealKey()): Map<number, SealCheck> {
  const rows = db
    .select()
    .from(monthSignoffs)
    .where(eq(monthSignoffs.userId, userId))
    .orderBy(asc(monthSignoffs.id))
    .all()
  const out = new Map<number, SealCheck>()
  let prev = ""
  for (const r of rows) {
    if (r.prevSeal !== prev) out.set(r.id, "chain_broken")
    else if (!sameText(computeSeal(r, key), r.seal)) out.set(r.id, "seal_mismatch")
    else if (r.reopenedAt == null && computeDigest(r.sealVersion === 1 ? 1 : 2, periodDataOf(r)) !== r.digest)
      out.set(r.id, "digest_mismatch")
    else out.set(r.id, "ok")
    prev = r.seal
  }
  return out
}

/** Verify the whole chain of one person; returns problems by sign-off id (empty = all fine). */
export function verifyUserChain(userId: number): Record<number, SealCheck> {
  const out: Record<number, SealCheck> = {}
  for (const [id, check] of checkUserChain(userId)) if (check !== "ok") out[id] = check
  return out
}

/** Seal of the person's latest sign-off (the next one chains to it), or "". */
export function lastSeal(userId: number): string {
  return (
    db
      .select({ seal: monthSignoffs.seal })
      .from(monthSignoffs)
      .where(eq(monthSignoffs.userId, userId))
      .orderBy(desc(monthSignoffs.id))
      .limit(1)
      .get()?.seal ?? ""
  )
}
